-- Death Note wow


















local LMG2L = {};

-- Players.CoffeLover764.PlayerGui.ScreenGui
LMG2L["ScreenGui_1"] = Instance.new("ScreenGui", game:GetService("Players").LocalPlayer:WaitForChild("PlayerGui"));
LMG2L["ScreenGui_1"]["ZIndexBehavior"] = Enum.ZIndexBehavior.Sibling;
LMG2L["ScreenGui_1"]["ResetOnSpawn"] = false

-- Players.CoffeLover764.PlayerGui.ScreenGui.ImageLabel
LMG2L["ImageLabel_2"] = Instance.new("ImageLabel", LMG2L["ScreenGui_1"]);
LMG2L["ImageLabel_2"]["BackgroundColor3"] = Color3.fromRGB(255, 255, 255);
-- LMG2L["ImageLabel_2"]["ImageContent"] = ;
LMG2L["ImageLabel_2"]["Image"] = [[rbxassetid://73470724125691]];
LMG2L["ImageLabel_2"]["Size"] = UDim2.new(0, 332, 0, 240);
LMG2L["ImageLabel_2"]["Position"] = UDim2.new(0, 678, 0, 202);
local camera = workspace.CurrentCamera
local frame = LMG2L["ImageLabel_2"]

local baseResolution = Vector2.new(1920,1080)
local basePosition = Vector2.new(678,202)

local function updatePosition()
	local size = camera.ViewportSize
	frame.Position = UDim2.new(0.32, basePosition.X * (size.X/baseResolution.X), 0.25, basePosition.Y * (size.Y/baseResolution.Y))
end

updatePosition()
camera:GetPropertyChangedSignal("ViewportSize"):Connect(updatePosition)

-- Players.CoffeLover764.PlayerGui.ScreenGui.ImageLabel.TextButton
LMG2L["TextButton_3"] = Instance.new("TextButton", LMG2L["ImageLabel_2"]);
LMG2L["TextButton_3"]["BorderSizePixel"] = 0;
LMG2L["TextButton_3"]["TextSize"] = 23;
LMG2L["TextButton_3"]["TextColor3"] = Color3.fromRGB(255, 255, 255);
LMG2L["TextButton_3"]["BackgroundColor3"] = Color3.fromRGB(255, 255, 255);
LMG2L["TextButton_3"]["FontFace"] = Font.new([[rbxasset://fonts/families/Nunito.json]], Enum.FontWeight.Regular, Enum.FontStyle.Normal);
LMG2L["TextButton_3"]["BackgroundTransparency"] = 1;
LMG2L["TextButton_3"]["Size"] = UDim2.new(0, 24, 0, 16);
LMG2L["TextButton_3"]["Text"] = [[X]];
LMG2L["TextButton_3"]["Position"] = UDim2.new(0, 2, 0, 6);


-- Players.CoffeLover764.PlayerGui.ScreenGui.ImageLabel.-- type here
LMG2L["-- type here_4"] = Instance.new("TextBox", LMG2L["ImageLabel_2"]);
LMG2L["-- type here_4"]["Name"] = [[-- type here]];
LMG2L["-- type here_4"]["TextXAlignment"] = Enum.TextXAlignment.Left;
LMG2L["-- type here_4"]["PlaceholderColor3"] = Color3.fromRGB(0, 0, 0);
LMG2L["-- type here_4"]["BorderSizePixel"] = 0;
LMG2L["-- type here_4"]["TextSize"] = 15;
LMG2L["-- type here_4"]["TextYAlignment"] = Enum.TextYAlignment.Top;
LMG2L["-- type here_4"]["BackgroundColor3"] = Color3.fromRGB(255, 255, 255);
LMG2L["-- type here_4"]["FontFace"] = Font.new([[rbxasset://fonts/families/Guru.json]], Enum.FontWeight.Regular, Enum.FontStyle.Normal);
LMG2L["-- type here_4"]["PlaceholderText"] = [[- type here]];
LMG2L["-- type here_4"]["Size"] = UDim2.new(0, 154, 0, 236);
LMG2L["-- type here_4"]["Position"] = UDim2.new(0, 186, 0, 26);
LMG2L["-- type here_4"]["Text"] = [[]];
LMG2L["-- type here_4"]["BackgroundTransparency"] = 1;
LMG2L["-- type here_4"]["TextWrapped"] = true
LMG2L["-- type here_4"]["MultiLine"] = true
local Players = game:GetService("Players")
LMG2L["TextButton_3"].MouseButton1Click:Connect(function()
	LMG2L["ScreenGui_1"]:Destroy()
end)

LMG2L["-- type here_4"].FocusLost:Connect(function(enterPressed)
	if enterPressed then
		local name = LMG2L["-- type here_4"].Text
		local target = Players:FindFirstChild(name)

		if target and target.Character and target.Character:FindFirstChild("Humanoid") then
			task.delay(5,function()
				if target.Character and target.Character:FindFirstChild("Humanoid") then
					target.Character.Humanoid.Health = 0
				end
			end)
		end
	end
end)
local UIS = game:GetService("UserInputService")

local dragging = false
local dragInput
local dragStart
local startPos

local function update(input)
	local delta = input.Position - dragStart
	frame.Position = UDim2.new(
		startPos.X.Scale,
		startPos.X.Offset + delta.X,
		startPos.Y.Scale,
		startPos.Y.Offset + delta.Y
	)
end

frame.InputBegan:Connect(function(input)
	if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
		dragging = true
		dragStart = input.Position
		startPos = frame.Position

		input.Changed:Connect(function()
			if input.UserInputState == Enum.UserInputState.End then
				dragging = false
			end
		end)
	end
end)

frame.InputChanged:Connect(function(input)
	if input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch then
		dragInput = input
	end
end)

UIS.InputChanged:Connect(function(input)
	if input == dragInput and dragging then
		update(input)
	end
end)

return LMG2L["ScreenGui_1"], require;
